def snapshot():
    families = copy.deepcopy([x for x in V2_FAMILIES if x["split"] == "train"] + NEW_FAMILIES)
    documents, queries = [], []
    for item in families:
        relevant = []
        for index, text in enumerate(item["profiles"]):
            identifier = f"{item['id']}-profile-{index + 1}"
            relevant.append(identifier)
            documents.append(dict(id=identifier, family=item["id"], role=item["role"], split=item["split"], text=text))
        for index, text in enumerate(item["queries"]):
            queries.append(dict(id=f"{item['id']}-query-{index + 1}", family=item["id"], role=item["role"], split=item["split"], text=text, relevant=list(relevant)))
    for split, texts in UNRELATED.items():
        for index, text in enumerate(texts):
            identifier = f"v3-unrelated-{split}-{index + 1}"
            queries.append(dict(id=identifier, family=identifier, role=None, split=split, text=text, relevant=[]))
    value = dict(schemaVersion=2, name="authored-task-retrieval-v3", relevance="explicit-task-family-qrels", documents=documents, queries=queries,
                 splitManifest=[dict(id=x["id"], role=x["role"], split=x["split"]) for x in families],
                 limitations=["Synthetic author judgments, not independently validated recruitment relevance.", "Only v2 train task families are reused; every dev/test task family and unrelated control is new.", "Two task-relevant profiles per query; a profession alone does not define relevance.", "The 42 functional benchmark queries are not corpus inputs or model-selection criteria.", "Independent functional regression cases do not determine this run's checkpoint or threshold."])
    validate(value)
    return value

def validate(value):
    validate_schema(value)
    assert len(value["splitManifest"]) == 84 and len(value["documents"]) == 168 and len(value["queries"]) == 276
    v2_heldout = [x for x in V2_FAMILIES if x["split"] != "train"]
    heldout_ids = {x["id"] for x in v2_heldout}
    assert not heldout_ids.intersection(x["id"] for x in value["splitManifest"]), "V2 held-out family reused"
    old_texts = {normalized(t) for x in v2_heldout for t in [*x["profiles"], *x["queries"]]}
    old_texts.update(normalized(t) for s in ("dev", "test") for t in V2_UNRELATED[s])
    assert not old_texts.intersection(normalized(x["text"]) for x in value["documents"] + value["queries"]), "V2 held-out text reused"
    for split in ("train", "dev", "test"):
        rows = [x for x in value["splitManifest"] if x["split"] == split]
        assert len(rows) == (56 if split == "train" else 14)
        for role in {x["role"] for x in rows}:
            assert sum(x["role"] == role for x in rows) == (4 if split == "train" else 1)
    return value

if __name__ == "__main__":
    value = snapshot()
    print(json.dumps(dict(sha256=dataset_hash(value), holdoutSha256=holdout_hash(value), families=len(value["splitManifest"]), documents=len(value["documents"]), queries=len(value["queries"]), splits={s: {k: len(v) for k, v in records(s, value).items()} for s in ("train", "dev", "test")}), ensure_ascii=False))
